import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"PumpkinPIE placeholders","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/distant-horizons-support-pumpkin/docs/placeholders.md"},"headers":[],"relativePath":"packages/distant-horizons-support-pumpkin/docs/placeholders.md","filePath":"packages/distant-horizons-support-pumpkin/docs/placeholders.md","lastUpdated":1792068294000}`),a={name:`packages/distant-horizons-support-pumpkin/docs/placeholders.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pumpkinpie-placeholders" tabindex="-1">PumpkinPIE placeholders <a class="header-anchor" href="#pumpkinpie-placeholders" aria-label="Permalink to “PumpkinPIE placeholders”">​</a></h1><p>Distant Horizons Support optionally registers the <code>dhs</code> namespace with PumpkinPIE. Every placeholder takes no argument and returns an unlocalized base-10 string. A known zero is <code>0</code>. Unknown names and supplied arguments are declined.</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Meaning</th></tr></thead><tbody><tr><td><code>%dhs_client_connected%</code></td><td>Whether the exact supplied viewer name has an active Distant Horizons session; true or false.</td></tr><tr><td><code>%dhs_clients%</code></td><td>Active Distant Horizons client sessions.</td></tr><tr><td><code>%dhs_pending_requests%</code></td><td>Number of pending LOD requests.</td></tr><tr><td><code>%dhs_worker_ticks%</code></td><td>Number of Distant Horizons worker ticks processed.</td></tr><tr><td><code>%dhs_served%</code></td><td>Number of LOD requests served.</td></tr><tr><td><code>%dhs_rejected%</code></td><td>Number of LOD requests rejected.</td></tr><tr><td><code>%dhs_cancelled%</code></td><td>Number of LOD requests cancelled.</td></tr><tr><td><code>%dhs_packet_bytes_sent%</code></td><td>Cumulative Distant Horizons packet bytes sent.</td></tr><tr><td><code>%dhs_cache_refreshes%</code></td><td>Number of current background cache refreshes.</td></tr><tr><td><code>%dhs_memory_entries%</code></td><td>Number of entries in the memory cache.</td></tr><tr><td><code>%dhs_memory_bytes%</code></td><td>Cached LOD payload byte lengths in memory, excluding JavaScript object overhead.</td></tr><tr><td><code>%dhs_memory_limit%</code></td><td>Memory cache entry limit; -1 means unlimited and 0 means disabled.</td></tr><tr><td><code>%dhs_disk_entries%</code></td><td>Number of entries indexed in the disk cache.</td></tr><tr><td><code>%dhs_disk_bytes%</code></td><td>Bytes indexed in the disk cache.</td></tr><tr><td><code>%dhs_disk_limit%</code></td><td>Disk cache entry limit; -1 means unlimited and 0 means disabled.</td></tr></tbody></table><p>All placeholders except <code>%dhs_client_connected%</code> work with or without a viewer. <code>%dhs_client_connected%</code> uses the exact, case-sensitive player name supplied by PumpkinPIE and returns <code>false</code> when that name has no active DH session. It is declined when no viewer is supplied. The viewer name is status context, not an authorization check.</p><p>These values are available to trusted plugins that can resolve PumpkinPIE placeholders; they do not inherit the operator permissions for <code>/dhs</code> commands.</p><p>For example, a scoreboard or chat format can include:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DH clients: %dhs_clients%; pending LOD requests: %dhs_pending_requests%</span></span>
<span class="line"><span>Memory cache: %dhs_memory_bytes% bytes across %dhs_memory_entries% entries</span></span>
<span class="line"><span>My DH session: %dhs_client_connected%</span></span></code></pre></div><p>PumpkinPIE is optional. Without it, Distant Horizons Support still loads and handles DH traffic. The plugin probes for PumpkinPIE with bounded exponential retry; after retries reach the cap, another attempt is scheduled no sooner than 5 minutes later. It recovers automatically on a scheduled attempt after PumpkinPIE becomes available. A ready integration sends its heartbeat every 30 seconds. No PumpkinPIE dependency is required in the host plugin metadata.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};